-- migration_039_extend_cannabinoid_tens_kbs_oct2026.sql
-- Extends two EXISTING knowledge boxes (batch 19). Only the knowledge-box portion of each explanation changes; option text unchanged. Idempotent (sets same value on re-run).
--   q_mtf_cannabinoid_receptors_001 -> "Cannabinoid System" + new sections: THC vs CBD, UK licensing and prescribing, NICE NG144, adverse effects
--   q_mtf_conventional_tens_001, q_sba_gate_control_tens_001 -> "TENS and Gate Control Theory" + new section "AL-TENS - Technique and Mechanism"
-- The 8 new batch-19 questions carry the same boxes byte-identically (migration_038).

update questions set data = jsonb_set(data, '{explanation}', to_jsonb($kb$<p>Cannabinoid receptors (CB1 and CB2) are pre-synaptic G-protein coupled receptors that mediate the effects of endogenous cannabinoids (endocannabinoids, e.g. anandamide, 2-AG) and exogenous cannabinoid drugs, playing important roles in pain modulation, inflammation, and neurotransmission.</p>
<p style="margin-top:12px"><strong>A. FALSE</strong> — Nabilone is a synthetic cannabinoid and a CB1/CB2 receptor agonist (not antagonist), used clinically for chemotherapy-induced nausea/vomiting and as an adjunct in some chronic pain settings.</p>
<p style="margin-top:12px"><strong>B. FALSE</strong> — CB1 receptors are the ones predominantly found in the CNS (particularly high density in areas like the hippocampus, cerebellum, and basal ganglia), mediating the classic psychoactive effects of cannabinoids. CB2 receptors are mainly found peripherally, particularly on immune cells (macrophages, microglia, lymphocytes), with comparatively limited CNS expression under normal conditions.</p>
<p style="margin-top:12px"><strong>C. TRUE</strong> — CB2 receptor expression is inducible and upregulated during inflammation and tissue injury, particularly on activated microglia and immune cells, which is why CB2 is of particular interest as a target for anti-inflammatory and analgesic drug development without the psychoactive effects associated with CB1.</p>
<p style="margin-top:12px"><strong>D. TRUE</strong> — Anandamide is an endogenous cannabinoid that, in addition to acting at CB1/CB2 receptors, is also an agonist at TRPV1 receptors, contributing to its complex and sometimes dual pro-nociceptive/anti-nociceptive effects depending on the receptor and location involved.</p>
<p style="margin-top:12px"><strong>E. TRUE</strong> — Presynaptic CB1 receptors are widely expressed on both excitatory (glutamatergic) and inhibitory (GABAergic) presynaptic terminals; activation of presynaptic CB1 receptors inhibits neurotransmitter release, including GABA release, forming the basis of "retrograde endocannabinoid signalling" in synaptic plasticity.</p>
<div style="margin-top:18px"><div style="border:1px solid var(--border-strong);border-radius:14px;overflow:hidden">
  <div style="display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)">
    <span style="font-weight:700;color:#fff;font-size:14.5px">Cannabinoid System</span>
    <div style="display:inline-flex;align-items:center;gap:7px;flex-shrink:0">
      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><line x1="12" y1="16" x2="12" y2="12"/><line x1="12" y1="8" x2="12.01" y2="8"/></svg>
      <span style="font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px">Knowledge</span>
    </div>
  </div>
  <div style="background:var(--surface-warm)"><div style="padding:16px 18px 14px;"><div style="margin-top:18px"><button type="button" class="nice-guideline-btn" onclick="openGuidelineModal('ng144','NG-144 Cannabis Products')">
  <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/><line x1="9" y1="13" x2="15" y2="13"/><line x1="9" y1="17" x2="15" y2="17"/></svg>
  NG-144 Cannabis Products
</button></div><p style="margin:14px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)">The endocannabinoid system (ECS) is a homeostatic signalling network involved in nociception, mood, appetite, memory, and immune function. It comprises cannabinoid receptors, endogenous ligands (endocannabinoids), and the enzymes that synthesise and degrade them.</p></div><div style="padding:16px 18px 14px;border-top:2px solid var(--border-strong);"><div style="font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px">Receptors</div><table style="margin:0"><tr><th>Receptor</th><th>Details</th></tr>
        <tr><td><strong>CB1</strong></td><td>Densely expressed in the CNS (particularly cortex, hippocampus, cerebellum, basal ganglia), with lower peripheral expression. Mediates the psychoactive effects of THC and modulates synaptic neurotransmitter release (both excitatory and inhibitory) via presynaptic inhibition.</td></tr>
        <tr><td><strong>CB2</strong></td><td>Less ubiquitous; acts by inhibiting proinflammatory responses of immune cells such as macrophages, lymphocytes, and microglia. Largely peripheral/immune in distribution, and upregulated in inflammatory states.</td></tr>
        <tr><td><strong>Signalling</strong></td><td>Both are G-protein coupled receptors, signalling via inhibition of adenylyl cyclase and reduced cAMP formation.</td></tr>
        </table></div><div style="padding:16px 18px 14px;border-top:2px solid var(--border-strong);"><div style="font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px">Beyond CB1/CB2 — Emerging Targets</div><table style="margin:0"><tr><th>Target</th><th>Details</th></tr>
        <tr><td><strong>GPR55</strong></td><td>An orphan receptor and its variants have been identified as new endocannabinoid-responsive receptors, sharing numerous cannabinoid ligands with CB1 and CB2, making it a potential therapeutic target for pain.</td></tr>
        <tr><td><strong>PPARs</strong></td><td>Peroxisome proliferator-activated receptors — nuclear transcription factors activated by cannabinoid-like molecules — have also been implicated in modulating inflammatory and neuropathic pain.</td></tr>
        <tr><td><strong>TRPV1</strong></td><td>Transient receptor potential channels, most notably TRPV1, have a prominent role in pain and interact with the endocannabinoid system (e.g. anandamide is a TRPV1 agonist as well as a CB1/CB2 ligand).</td></tr>
        </table></div><div style="padding:16px 18px 14px;border-top:2px solid var(--border-strong);"><div style="font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px">Ligands</div><table style="margin:0"><tr><th>Class</th><th>Details</th></tr>
        <tr><td><strong>Endocannabinoids</strong></td><td>Anandamide and 2-arachidonoylglycerol (2-AG), synthesised on demand from membrane phospholipids, acting as retrograde messengers at presynaptic terminals.</td></tr>
        <tr><td><strong>Phytocannabinoids</strong></td><td>THC (partial CB1/CB2 agonist, psychoactive) and cannabidiol (CBD, non-psychoactive, complex/indirect pharmacology).</td></tr>
        <tr><td><strong>Synthetic cannabinoids</strong></td><td>e.g. nabilone (CB1/CB2 agonist, used for chemotherapy-induced nausea/vomiting and occasionally chronic pain).</td></tr>
        </table></div><div style="padding:16px 18px 14px;border-top:2px solid var(--border-strong);"><div style="font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px">Clinical Relevance in Pain Medicine</div><table style="margin:0"><tr><th>Point</th><th>Details</th></tr>
        <tr><td><strong>Preclinical</strong></td><td>Cannabinoids have shown effective anti-nociception in numerous animal models of chronic inflammatory and neuropathic pain, with evidence supporting anti-nociception from dual CB1/CB2 agonists as well as receptor-specific agonists.</td></tr>
        <tr><td><strong>Clinical evidence</strong></td><td>Human trial evidence is more limited and heterogeneous than preclinical data, particularly for chronic non-cancer pain, with modest effect sizes and significant variability between studies.</td></tr>
        <tr><td><strong>Direction of travel</strong></td><td>Clinical interest is moving toward peripherally-restricted or receptor-selective agonists to try to separate analgesic benefit from central psychoactive/psychotomimetic side effects.</td></tr>
        </table></div><div style="padding:16px 18px 14px;border-top:2px solid var(--border-strong);"><div style="font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px">Phytocannabinoids &mdash; THC versus CBD</div><table style="margin:0"><tr><th>Feature</th><th>THC (&Delta;9-tetrahydrocannabinol)</th><th>CBD (cannabidiol)</th></tr><tr><td><strong>Receptor action</strong></td><td>Partial agonist at CB1 and CB2</td><td>Very low affinity for the CB1/CB2 orthosteric site; acts as a negative allosteric modulator of CB1, with actions at TRPV1, 5-HT1A and other targets</td></tr><tr><td><strong>Psychoactivity</strong></td><td>Responsible for the &ldquo;high&rdquo;, anxiety and psychotomimetic effects</td><td>Not intoxicating; may attenuate some THC effects</td></tr><tr><td><strong>Metabolism</strong></td><td>Hepatic CYP450 (mainly CYP2C9, also CYP3A4) to <strong>11-hydroxy-THC</strong>, an active metabolite, then to inactive 11-nor-9-carboxy-THC</td><td>Hepatic (CYP2C19, CYP3A4); <strong>inhibits CYP2C19</strong>, raising levels of the active metabolite of clobazam</td></tr><tr><td><strong>Examples</strong></td><td>Dronabinol; component of nabiximols</td><td>Epidyolex; component of nabiximols</td></tr></table></div><div style="padding:16px 18px 14px;border-top:2px solid var(--border-strong);"><div style="font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px">UK Licensing and Prescribing</div><table style="margin:0"><tr><th>Product</th><th>Composition</th><th>UK status / licensed use</th></tr><tr><td><strong>Nabilone</strong></td><td>Synthetic THC analogue (CB1/CB2 agonist)</td><td>Licensed for chemotherapy-induced nausea and vomiting unresponsive to conventional antiemetics. Off-label use in pain.</td></tr><tr><td><strong>Nabiximols (Sativex)</strong></td><td>Oromucosal spray, THC:CBD approximately 1:1</td><td>Licensed as add-on for moderate to severe spasticity in multiple sclerosis not responding to other antispasticity drugs. Not licensed for pain.</td></tr><tr><td><strong>Cannabidiol (Epidyolex)</strong></td><td>Purified CBD oral solution</td><td>Licensed with clobazam for seizures in Dravet syndrome and Lennox-Gastaut syndrome (and tuberous sclerosis complex).</td></tr><tr><td><strong>Dronabinol, herbal/flower, oils</strong></td><td>THC or whole-plant products</td><td>Dronabinol has no UK licence for pain. Others are unlicensed &ldquo;specials&rdquo; (cannabis-based products for medicinal use in humans, CBPMs).</td></tr></table><p style="margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)">Since 1 November 2018, CBPMs have been lawful to prescribe as Schedule 2 controlled drugs (Misuse of Drugs Regulations 2001, as amended). Prescribing may be <strong>initiated only by doctors on the GMC specialist register</strong>, usually after specialist multidisciplinary advice; GPs may continue treatment started by a specialist under shared care.</p><p style="margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)">Most CBPMs are unlicensed, so prescribing is on a named-patient basis with the prescriber taking responsibility. Cannabis is a Schedule 1 drug under the 2001 Regulations unless it is a CBPM; recreational cannabis remains Class B under the Misuse of Drugs Act 1971.</p></div><div style="padding:16px 18px 14px;border-top:2px solid var(--border-strong);"><div style="font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px">NICE NG144 &mdash; Cannabis-based Medicinal Products</div><table style="margin:0"><tr><th>Indication</th><th>NICE recommendation</th></tr><tr><td><strong>Chemotherapy-induced nausea and vomiting</strong></td><td>Offer nabilone to adults if conventional antiemetics have failed. Do not offer nabiximols, dronabinol or CBD.</td></tr><tr><td><strong>MS spasticity</strong></td><td>Consider nabiximols as add-on if other treatments have not worked; review at 4 weeks and continue only if there is a clinically meaningful (at least 20%) improvement.</td></tr><tr><td><strong>Severe treatment-resistant epilepsy</strong></td><td>Consider Epidyolex with clobazam for Dravet syndrome and Lennox-Gastaut syndrome.</td></tr><tr><td><strong>Chronic pain in adults</strong></td><td><strong>Do not offer</strong> cannabis-based medicinal products (THC with or without CBD, nabilone, dronabinol) for chronic pain outside a clinical trial, because of insufficient evidence of benefit and concern about harms.</td></tr></table></div><div style="padding:16px 18px 14px;border-top:2px solid var(--border-strong);"><div style="font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px">Adverse Effects</div><table style="margin:0"><tr><th>System</th><th>Effect</th></tr><tr><td><strong>CNS</strong></td><td>Drowsiness, dizziness, impaired cognition and coordination, anxiety, dysphoria, impaired driving ability</td></tr><tr><td><strong>Psychiatric</strong></td><td>Psychotic symptoms, particularly with high-potency THC and in those predisposed; dependence</td></tr><tr><td><strong>Cardiovascular</strong></td><td>Tachycardia, postural hypotension</td></tr><tr><td><strong>Respiratory</strong></td><td>Little or no clinically important respiratory depression (in contrast to opioids)</td></tr><tr><td><strong>Withdrawal</strong></td><td>Irritability, insomnia, reduced appetite, restlessness after abrupt cessation following prolonged use</td></tr><tr><td><strong>Other</strong></td><td>Dry mouth, increased appetite, nausea; THC is a specified drug under the 2015 drug-driving regulations</td></tr></table><p style="margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)">Cannabinoids are contraindicated or used with great caution in patients with a personal or family history of psychosis, severe cardiovascular disease, and in pregnancy.</p></div></div>
</div></div>$kb$::text)) where id = 'q_mtf_cannabinoid_receptors_001';
update questions set data = jsonb_set(data, '{explanation}', to_jsonb($kb$<p>Conventional TENS uses high-frequency, low-intensity stimulation to preferentially activate large-diameter A&beta; fibres, producing analgesia mainly through the spinal gate-control mechanism and opioid-mediated pathways, and understanding its parameters and safety profile is frequently tested.</p>
<p style="margin-top:12px"><strong>A. TRUE</strong> — Conventional TENS typically uses a <strong>high frequency of 50&ndash;100 Hz</strong>, delivered at low intensity, producing a comfortable tingling/buzzing sensation without visible muscle contraction.</p>
<p style="margin-top:12px"><strong>B. FALSE</strong> — The typical pulse <strong>width</strong> (duration) for conventional TENS is in the range of <strong>50&ndash;200 microseconds</strong>, not milliseconds &mdash; this is a common unit-based exam trap; a pulse width of milliseconds would be several orders of magnitude too long and outside standard TENS parameters.</p>
<p style="margin-top:12px"><strong>C. FALSE</strong> — TENS manufacturers list cardiac pacemakers, pregnancy, and epilepsy as contraindications largely because it may be difficult to exclude TENS as a cause of a problem from a legal perspective. In practice, TENS can be used safely in patients with epilepsy; there is no established mechanism by which peripheral transcutaneous electrical stimulation would provoke seizure activity. Recognised contraindications instead include use over the carotid sinus, in patients with cardiac pacemakers/implantable defibrillators, and over the pregnant abdomen.</p>
<p style="margin-top:12px"><strong>D. FALSE</strong> — Conventional TENS does <strong>not</strong> work primarily through GABA modulation; its main proposed mechanisms are the <strong>gate control theory</strong> (activation of large A&beta; fibres inhibiting nociceptive transmission at the dorsal horn) and spinal <strong>delta-opioid receptor</strong> activation.</p>
<p style="margin-top:12px"><strong>E. TRUE</strong> — TENS is contraindicated (or requires specialist caution) in patients with cardiac pacemakers or implantable cardioverter-defibrillators (ICDs), due to the risk of electrical interference with device function; TENS electrodes should also not be placed near the device itself even where cautious use is considered acceptable.</p>
<div style="margin-top:18px"><div style="border:1px solid var(--border-strong);border-radius:14px;overflow:hidden">
  <div style="display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)">
    <span style="font-weight:700;color:#fff;font-size:14.5px">TENS and Gate Control Theory</span>
    <div style="display:inline-flex;align-items:center;gap:7px;flex-shrink:0">
      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><line x1="12" y1="16" x2="12" y2="12"/><line x1="12" y1="8" x2="12.01" y2="8"/></svg>
      <span style="font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px">Knowledge</span>
    </div>
  </div>
  <div style="background:var(--surface-warm)"><div style="padding:16px 18px 14px;"><p style="margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)">Transcutaneous Electrical Nerve Stimulation (TENS) is a non-invasive, low-cost, patient-controlled method of pain relief. A small battery-powered pulse generator delivers electrical pulses to the skin through adhesive surface electrodes.</p><p style="margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)">Parameters that can be modified on a TENS machine include pulse duration (in microseconds), pulse frequency (in Hz or pulses/sec) and pulse amplitude (in milliamperes).</p></div><div style="padding:16px 18px 14px;border-top:2px solid var(--border-strong);"><div style="font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px">Gate Control Theory</div><p style="margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)">Melzack and Wall (1965) proposed that the substantia gelatinosa (lamina II) acts as a &ldquo;gate&rdquo; modulating transmission to the dorsal horn projection (T) neurone. The balance of large-fibre and small-fibre input, together with descending control from the brain, determines whether the gate is open or closed.</p><div style="text-align:center"><img src="images/gate-control-theory.svg" alt="Diagram of the gate control theory: A-beta afferents excite the substantia gelatinosa inhibitory interneuron and the projection T cell; A-delta and C afferents inhibit the interneuron and excite the T cell; descending brain pathways modulate the interneuron; the T cell projects via the spinothalamic tract" style="max-width:100%;border-radius:10px;margin-top:4px;border:1px solid #EDE3D7"></div></div><div style="padding:16px 18px 14px;border-top:2px solid var(--border-strong);"><div style="font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px">Effect on the Gate</div><table style="margin:0"><tr><th>Input</th><th>Effect on SG inhibitory interneurone</th><th>Effect on T cell</th><th>Net result</th></tr><tr><td>A&beta; (large fibres)</td><td>Excites</td><td>Excites, but also inhibited via interneurone</td><td>Gate closes; less pain transmitted</td></tr><tr><td>A&delta; and C (small fibres)</td><td>Inhibits</td><td>Excites</td><td>Gate opens; more pain transmitted</td></tr><tr><td>Descending brain pathways</td><td>Modulate (usually enhance inhibition)</td><td>Indirect</td><td>Gate closes (attention, expectation, descending inhibition)</td></tr></table><table style="margin:12px 0 0"><tr><th>Application of the gate concept</th><th>Principle</th></tr><tr><td>Rubbing a bruise or shaking a hand after injury</td><td>Everyday recruitment of A&beta; fibres</td></tr><tr><td>Conventional TENS</td><td>Comfortable paraesthesia over the painful area; A&beta; recruitment closes the gate</td></tr><tr><td>Spinal cord stimulation</td><td>Developed from gate control theory; paraesthesia-based SCS stimulates dorsal column A&beta; fibres</td></tr></table><p style="margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)">Modern interpretations place greater emphasis on GABA/glycine-mediated inhibition. Loss of this inhibition (disinhibition) after nerve injury can allow A&beta; input to drive nociceptive circuits, producing mechanical allodynia.</p></div><div style="padding:16px 18px 14px;border-top:2px solid var(--border-strong);"><div style="font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px">Types of TENS</div><table style="margin:0"><tr><th>Type</th><th>Frequency</th><th>Intensity</th><th>Fibres activated</th><th>Proposed mechanism</th></tr><tr><td><strong>Conventional TENS</strong></td><td>High (~50&ndash;100 Hz)</td><td>Low &mdash; comfortable tingling, no visible contraction</td><td>Large-diameter A&beta; afferents</td><td>Segmental gate-control inhibition of dorsal horn transmission; spinal delta-opioid receptor involvement</td></tr><tr><td><strong>Acupuncture-like TENS (AL-TENS)</strong></td><td>Low (~2&ndash;4 Hz)</td><td>High &mdash; visible muscle twitching</td><td>Smaller A&delta; afferents / motor efferents</td><td>Extrasegmental, opioid-mediated (mu-receptor) analgesia via activation of descending inhibitory pathways</td></tr><tr><td><strong>Intense TENS</strong></td><td>High</td><td>Very high &mdash; at or near the limit of tolerability</td><td>Small-diameter A&delta; (and some C) fibres</td><td>Counter-irritation / hyperstimulation analgesia; typically used briefly for short, painful procedures (e.g. wound dressing changes, injections) rather than continuously, as tolerance to the high intensity limits prolonged application</td></tr></table></div><div style="padding:16px 18px 14px;border-top:2px solid var(--border-strong);"><div style="font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px">AL-TENS &mdash; Technique and Mechanism</div><table style="margin:0"><tr><th>Feature</th><th>Acupuncture-like TENS</th></tr><tr><td><strong>Frequency</strong></td><td>Low, about 2&ndash;4 Hz (often delivered as bursts of higher-frequency pulses at 2&ndash;4 bursts per second)</td></tr><tr><td><strong>Pulse width</strong></td><td>Relatively long, typically about 200 &micro;s</td></tr><tr><td><strong>Intensity</strong></td><td>High but tolerable: strong, <strong>rhythmic visible muscle twitching</strong> without discomfort</td></tr><tr><td><strong>Electrode placement</strong></td><td>Over motor points/muscle bellies, myotomes or acupuncture points, often proximal to the pain; <strong>extrasegmental</strong>, so does not require normal sensation at the painful site</td></tr><tr><td><strong>Mechanism</strong></td><td>Activates small-diameter afferents from muscle (A&delta;/group III) and motor efferents, releasing <strong>endogenous opioids</strong> (&beta;-endorphin, enkephalins) acting at spinal and supraspinal <strong>mu-opioid receptors</strong> and engaging descending inhibition (periaqueductal grey and rostral ventromedial medulla)</td></tr><tr><td><strong>Naloxone</strong></td><td>Analgesia is <strong>reversed by naloxone</strong></td></tr><tr><td><strong>Tolerance</strong></td><td>Repeated use leads to tolerance with <strong>cross-tolerance to morphine</strong> (mu-opioid agonists)</td></tr><tr><td><strong>Time-course</strong></td><td>Slower onset than conventional TENS; analgesia may <strong>outlast</strong> the stimulation period</td></tr></table><p style="margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)">Conventional TENS (high frequency, low intensity, comfortable paraesthesia) acts largely through segmental gate-control mechanisms and spinal delta-opioid receptors. Contraindications are the same for both modes.</p></div><div style="padding:16px 18px 14px;border-top:2px solid var(--border-strong);"><div style="font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px">TENS Contraindications</div><table style="margin:0"><tr><th>Contraindication / precaution</th><th>Reason</th></tr><tr><td>Cardiac implantable devices</td><td>Pacemakers and implantable cardioverter-defibrillators &mdash; electrical interference can disrupt device sensing/pacing.</td></tr><tr><td>Over the carotid sinus</td><td>Risk of provoking a vasovagal/hypotensive response.</td></tr><tr><td>Over the anterior neck / larynx</td><td>Risk of laryngospasm or interference with airway reflexes.</td></tr><tr><td>Pregnancy</td><td>Avoid placement over the abdomen or lower back, particularly in early pregnancy, due to theoretical uterine stimulation risk (direct evidence of harm is limited).</td></tr><tr><td>Active malignancy at the treatment site</td><td>Theoretical concern regarding electrical stimulation of tumour tissue, though evidence is limited.</td></tr><tr><td>Broken/irritated skin, adhesive allergy</td><td>Local skin precautions.</td></tr><tr><td>Driving, operating machinery, or sleep</td><td>Devices should never be applied then, given the reliance on patient feedback for safe intensity titration.</td></tr><tr><td>Dysaesthesia / diminished sensation</td><td>TENS should not be applied to skin with diminished sensation &mdash; nerve damage is likely to reduce effectiveness and the patient may be unaware that high-intensity currents are causing skin irritation. Caution with mechanical allodynia, as TENS may exacerbate the pain.</td></tr></table></div><div style="padding:16px 18px 14px;border-top:2px solid var(--border-strong);"><div style="font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px">Effectiveness</div><p style="margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)">Clinical experience suggests that TENS may relieve any type of chronic pain, yet systematic reviews are inconclusive for chronic pain, low back pain, cancer-related pain, rheumatoid arthritis of the hand, post-stroke shoulder pain, whiplash and mechanical neck disorders, and chronic recurrent headache. Meta-analyses for osteoarthritic knee pain and for chronic musculoskeletal pain have been more positive, suggesting that TENS is superior to sham TENS for pain and stiffness. Non-randomised controlled clinical trials have found benefit for many types of chronic pain.</p><p style="margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)">NICE guidance does <strong>not</strong> recommend routinely offering TENS for chronic low back pain.</p></div></div>
</div></div>$kb$::text)) where id = 'q_mtf_conventional_tens_001';
update questions set data = jsonb_set(data, '{explanation}', to_jsonb($kb$<p style="margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)">The gate control theory (Melzack and Wall, 1965) proposed that dorsal horn transmission of nociceptive input is regulated by competing input from large and small fibres, acting through inhibitory interneurones of the substantia gelatinosa. Conventional TENS is the clinical application of this idea.</p><p style="margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)"><strong>A. Incorrect.</strong> TENS at conventional settings produces a comfortable paraesthesia without pain and does not block conduction in C fibres; the nerve is not anaesthetised.</p><p style="margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)"><strong>B. Correct.</strong> Low-intensity, high-frequency stimulation preferentially recruits large A&beta; fibres (lowest electrical threshold). These excite substantia gelatinosa inhibitory interneurones, which inhibit the projection (T) neurone and &ldquo;close the gate&rdquo; to nociceptive input from A&delta; and C fibres.</p><p style="margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)"><strong>C. Incorrect.</strong> Substance P depletion is the mechanism of topical capsaicin, not TENS.</p><p style="margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)"><strong>D. Incorrect.</strong> Strong, low-frequency (2&ndash;4 Hz), high-intensity &ldquo;acupuncture-like&rdquo; TENS is thought to work by recruiting small fibres and opioid-mediated descending inhibition. This is not the mechanism of conventional high-frequency TENS.</p><p style="margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)"><strong>E. Incorrect.</strong> NMDA receptor antagonism is the mechanism of ketamine and similar agents, not TENS.</p><div style="margin-top:18px"><div style="border:1px solid var(--border-strong);border-radius:14px;overflow:hidden">
  <div style="display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)">
    <span style="font-weight:700;color:#fff;font-size:14.5px">TENS and Gate Control Theory</span>
    <div style="display:inline-flex;align-items:center;gap:7px;flex-shrink:0">
      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><line x1="12" y1="16" x2="12" y2="12"/><line x1="12" y1="8" x2="12.01" y2="8"/></svg>
      <span style="font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px">Knowledge</span>
    </div>
  </div>
  <div style="background:var(--surface-warm)"><div style="padding:16px 18px 14px;"><p style="margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)">Transcutaneous Electrical Nerve Stimulation (TENS) is a non-invasive, low-cost, patient-controlled method of pain relief. A small battery-powered pulse generator delivers electrical pulses to the skin through adhesive surface electrodes.</p><p style="margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)">Parameters that can be modified on a TENS machine include pulse duration (in microseconds), pulse frequency (in Hz or pulses/sec) and pulse amplitude (in milliamperes).</p></div><div style="padding:16px 18px 14px;border-top:2px solid var(--border-strong);"><div style="font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px">Gate Control Theory</div><p style="margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)">Melzack and Wall (1965) proposed that the substantia gelatinosa (lamina II) acts as a &ldquo;gate&rdquo; modulating transmission to the dorsal horn projection (T) neurone. The balance of large-fibre and small-fibre input, together with descending control from the brain, determines whether the gate is open or closed.</p><div style="text-align:center"><img src="images/gate-control-theory.svg" alt="Diagram of the gate control theory: A-beta afferents excite the substantia gelatinosa inhibitory interneuron and the projection T cell; A-delta and C afferents inhibit the interneuron and excite the T cell; descending brain pathways modulate the interneuron; the T cell projects via the spinothalamic tract" style="max-width:100%;border-radius:10px;margin-top:4px;border:1px solid #EDE3D7"></div></div><div style="padding:16px 18px 14px;border-top:2px solid var(--border-strong);"><div style="font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px">Effect on the Gate</div><table style="margin:0"><tr><th>Input</th><th>Effect on SG inhibitory interneurone</th><th>Effect on T cell</th><th>Net result</th></tr><tr><td>A&beta; (large fibres)</td><td>Excites</td><td>Excites, but also inhibited via interneurone</td><td>Gate closes; less pain transmitted</td></tr><tr><td>A&delta; and C (small fibres)</td><td>Inhibits</td><td>Excites</td><td>Gate opens; more pain transmitted</td></tr><tr><td>Descending brain pathways</td><td>Modulate (usually enhance inhibition)</td><td>Indirect</td><td>Gate closes (attention, expectation, descending inhibition)</td></tr></table><table style="margin:12px 0 0"><tr><th>Application of the gate concept</th><th>Principle</th></tr><tr><td>Rubbing a bruise or shaking a hand after injury</td><td>Everyday recruitment of A&beta; fibres</td></tr><tr><td>Conventional TENS</td><td>Comfortable paraesthesia over the painful area; A&beta; recruitment closes the gate</td></tr><tr><td>Spinal cord stimulation</td><td>Developed from gate control theory; paraesthesia-based SCS stimulates dorsal column A&beta; fibres</td></tr></table><p style="margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)">Modern interpretations place greater emphasis on GABA/glycine-mediated inhibition. Loss of this inhibition (disinhibition) after nerve injury can allow A&beta; input to drive nociceptive circuits, producing mechanical allodynia.</p></div><div style="padding:16px 18px 14px;border-top:2px solid var(--border-strong);"><div style="font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px">Types of TENS</div><table style="margin:0"><tr><th>Type</th><th>Frequency</th><th>Intensity</th><th>Fibres activated</th><th>Proposed mechanism</th></tr><tr><td><strong>Conventional TENS</strong></td><td>High (~50&ndash;100 Hz)</td><td>Low &mdash; comfortable tingling, no visible contraction</td><td>Large-diameter A&beta; afferents</td><td>Segmental gate-control inhibition of dorsal horn transmission; spinal delta-opioid receptor involvement</td></tr><tr><td><strong>Acupuncture-like TENS (AL-TENS)</strong></td><td>Low (~2&ndash;4 Hz)</td><td>High &mdash; visible muscle twitching</td><td>Smaller A&delta; afferents / motor efferents</td><td>Extrasegmental, opioid-mediated (mu-receptor) analgesia via activation of descending inhibitory pathways</td></tr><tr><td><strong>Intense TENS</strong></td><td>High</td><td>Very high &mdash; at or near the limit of tolerability</td><td>Small-diameter A&delta; (and some C) fibres</td><td>Counter-irritation / hyperstimulation analgesia; typically used briefly for short, painful procedures (e.g. wound dressing changes, injections) rather than continuously, as tolerance to the high intensity limits prolonged application</td></tr></table></div><div style="padding:16px 18px 14px;border-top:2px solid var(--border-strong);"><div style="font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px">AL-TENS &mdash; Technique and Mechanism</div><table style="margin:0"><tr><th>Feature</th><th>Acupuncture-like TENS</th></tr><tr><td><strong>Frequency</strong></td><td>Low, about 2&ndash;4 Hz (often delivered as bursts of higher-frequency pulses at 2&ndash;4 bursts per second)</td></tr><tr><td><strong>Pulse width</strong></td><td>Relatively long, typically about 200 &micro;s</td></tr><tr><td><strong>Intensity</strong></td><td>High but tolerable: strong, <strong>rhythmic visible muscle twitching</strong> without discomfort</td></tr><tr><td><strong>Electrode placement</strong></td><td>Over motor points/muscle bellies, myotomes or acupuncture points, often proximal to the pain; <strong>extrasegmental</strong>, so does not require normal sensation at the painful site</td></tr><tr><td><strong>Mechanism</strong></td><td>Activates small-diameter afferents from muscle (A&delta;/group III) and motor efferents, releasing <strong>endogenous opioids</strong> (&beta;-endorphin, enkephalins) acting at spinal and supraspinal <strong>mu-opioid receptors</strong> and engaging descending inhibition (periaqueductal grey and rostral ventromedial medulla)</td></tr><tr><td><strong>Naloxone</strong></td><td>Analgesia is <strong>reversed by naloxone</strong></td></tr><tr><td><strong>Tolerance</strong></td><td>Repeated use leads to tolerance with <strong>cross-tolerance to morphine</strong> (mu-opioid agonists)</td></tr><tr><td><strong>Time-course</strong></td><td>Slower onset than conventional TENS; analgesia may <strong>outlast</strong> the stimulation period</td></tr></table><p style="margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)">Conventional TENS (high frequency, low intensity, comfortable paraesthesia) acts largely through segmental gate-control mechanisms and spinal delta-opioid receptors. Contraindications are the same for both modes.</p></div><div style="padding:16px 18px 14px;border-top:2px solid var(--border-strong);"><div style="font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px">TENS Contraindications</div><table style="margin:0"><tr><th>Contraindication / precaution</th><th>Reason</th></tr><tr><td>Cardiac implantable devices</td><td>Pacemakers and implantable cardioverter-defibrillators &mdash; electrical interference can disrupt device sensing/pacing.</td></tr><tr><td>Over the carotid sinus</td><td>Risk of provoking a vasovagal/hypotensive response.</td></tr><tr><td>Over the anterior neck / larynx</td><td>Risk of laryngospasm or interference with airway reflexes.</td></tr><tr><td>Pregnancy</td><td>Avoid placement over the abdomen or lower back, particularly in early pregnancy, due to theoretical uterine stimulation risk (direct evidence of harm is limited).</td></tr><tr><td>Active malignancy at the treatment site</td><td>Theoretical concern regarding electrical stimulation of tumour tissue, though evidence is limited.</td></tr><tr><td>Broken/irritated skin, adhesive allergy</td><td>Local skin precautions.</td></tr><tr><td>Driving, operating machinery, or sleep</td><td>Devices should never be applied then, given the reliance on patient feedback for safe intensity titration.</td></tr><tr><td>Dysaesthesia / diminished sensation</td><td>TENS should not be applied to skin with diminished sensation &mdash; nerve damage is likely to reduce effectiveness and the patient may be unaware that high-intensity currents are causing skin irritation. Caution with mechanical allodynia, as TENS may exacerbate the pain.</td></tr></table></div><div style="padding:16px 18px 14px;border-top:2px solid var(--border-strong);"><div style="font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px">Effectiveness</div><p style="margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)">Clinical experience suggests that TENS may relieve any type of chronic pain, yet systematic reviews are inconclusive for chronic pain, low back pain, cancer-related pain, rheumatoid arthritis of the hand, post-stroke shoulder pain, whiplash and mechanical neck disorders, and chronic recurrent headache. Meta-analyses for osteoarthritic knee pain and for chronic musculoskeletal pain have been more positive, suggesting that TENS is superior to sham TENS for pain and stiffness. Non-randomised controlled clinical trials have found benefit for many types of chronic pain.</p><p style="margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)">NICE guidance does <strong>not</strong> recommend routinely offering TENS for chronic low back pain.</p></div></div>
</div></div>$kb$::text)) where id = 'q_sba_gate_control_tens_001';
